package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.core.*;import net.minecraft.nbt.*;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.item.context.*;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.phys.*;import net.minecraft.network.chat.Component;import java.util.*;
public final class DefenseItem extends BlockItem{
 public final int kind;public DefenseItem(Block block,Properties p,int kind){super(block,p);this.kind=kind;}public static CompoundTag data(ItemStack s){return s.hasTag()?s.getTag().copy():new CompoundTag();}public static void data(ItemStack s,CompoundTag n){s.setTag(n);}public static Direction face(Player p,ItemStack stack){Direction d=p==null?Direction.SOUTH:p.getDirection().getOpposite();for(int i=0;i<(data(stack).getInt("DefenseRotation")&3);i++)d=d.getClockWise();return d;}
 @Override public InteractionResult useOn(UseOnContext c){if(c.getPlayer()!=null&&c.getPlayer().isShiftKeyDown()){var n=data(c.getItemInHand());n.putInt("DefenseRotation",(n.getInt("DefenseRotation")+1)&3);data(c.getItemInHand(),n);return InteractionResult.SUCCESS;}return super.useOn(c);}
 public static BlockPos anchor(BlockPos above,Direction face,int kind){return above.relative(face.getOpposite(),kind==0?5:7);}
 @Override public BlockPlaceContext updatePlacementContext(BlockPlaceContext c){if(c.getClickedFace()!=Direction.UP)return null;var root=anchor(c.getClickedPos(),face(c.getPlayer(),c.getItemInHand()),kind);if(!BunkerVegetation.replaceable(c.getLevel(),root))return null;return BunkerVegetation.at(c,root);}
 public static String check(Level l,BlockPos root,Direction face,int kind,Player player,ItemStack stack){var geo=DefenseGeometry.MODELS[kind];var bounds=geo.worldBox(root,face,geo.bounds);if(bounds.minY<l.getMinBuildHeight()||bounds.maxY>l.getMaxBuildHeight())return "HEIGHT";for(var p:BlockPos.betweenClosed(BlockPos.containing(bounds.minX,bounds.minY,bounds.minZ),BlockPos.containing(bounds.maxX-.00001,bounds.maxY-.00001,bounds.maxZ-.00001))){if(!l.hasChunkAt(p))return "UNLOADED";if(!l.getWorldBorder().isWithinBounds(p)||player!=null&&(!l.mayInteract(player,p)||!player.mayUseItemAt(p,Direction.UP,stack)))return "DENIED";if(!BunkerVegetation.replaceable(l,p))return "BLOCKED";}for(var c:geo.support){var p=geo.cell(root,face,c).below();if(!l.getBlockState(p).isFaceSturdy(l,p,Direction.UP))return "FOUNDATION";}if(!l.getEntities((net.minecraft.world.entity.Entity)null,bounds,e->!e.isSpectator()&&!(e instanceof net.minecraft.world.entity.item.ItemEntity)&&!(e instanceof net.minecraft.world.entity.ExperienceOrb)).isEmpty())return "OCCUPIED";return "";}
 @Override protected boolean canPlace(BlockPlaceContext c,BlockState state){var why=check(c.getLevel(),c.getClickedPos(),state.getValue(DefenseBlock.FACING),kind,c.getPlayer(),c.getItemInHand());if(!why.isEmpty()&&c.getPlayer()!=null)c.getPlayer().displayClientMessage(Component.translatable("defense.status."+why),true);return why.isEmpty()&&super.canPlace(c,state);}
 @Override protected boolean placeBlock(BlockPlaceContext c,BlockState state){var tx=new BunkerVegetation.Transaction(c.getLevel());DefenseBlock.MUTATING.set(true);try{var geo=DefenseGeometry.MODELS[kind];if(!tx.clear(geo.worldBox(c.getClickedPos(),state.getValue(DefenseBlock.FACING),geo.bounds)))return false;for(int i=0;i<geo.cells.length;i++){var p=geo.cell(c.getClickedPos(),state.getValue(DefenseBlock.FACING),geo.cells[i]);if(!tx.set(p,state.setValue(DefenseBlock.PART,i))){tx.rollback();return false;}}return true;}finally{DefenseBlock.MUTATING.set(false);}}
 @Override public void appendHoverText(ItemStack s,Level l,List<Component>text,TooltipFlag flag){text.add(Component.translatable(kind==0?"defense.pl01.description":"defense.dr01.description"));text.add(Component.translatable("defense.placement"));}
 @Override public void initializeClient(java.util.function.Consumer<net.minecraftforge.client.extensions.common.IClientItemExtensions> c){c.accept(new net.minecraftforge.client.extensions.common.IClientItemExtensions(){@Override public net.minecraft.client.renderer.BlockEntityWithoutLevelRenderer getCustomRenderer(){return DefenseItemRenderer.instance();}});}
}
